1	// Deno Deploy / Supabase Edge Function for Resend webhook
2	import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
3	import { Webhook } from 'https://esm.sh/svix@1.15.0';
4	import { ocrFromUrl, processEmailText, textToImage } from '../_shared/mistral.ts';
5	import { resolveOcrReceiptDate } from '../_shared/receiptDateCorrection.ts';
6	import { fetchExchangeRate } from '../_shared/exchangeRate.ts';
7	import {
8		isSupportedReceiptType,
9		isInlineAttachment,
10		hasUsableOcrData,
11		hasSupportedAttachments
12	} from '../_shared/attachmentFiltering.ts';
13	import {
14		sendNotificationEmail as sendResendNotification,
15		type NotificationType
16	} from '../_shared/notify.ts';
17	import { parseSenderEmail } from '../_shared/emailParsing.ts';
18	import { errText } from '../_shared/errText.ts';
19	
20	interface ResendAttachmentMetadata {
21		id: string;
22		filename: string;
23		content_type: string;
24		content_disposition?: string;
25		content_id?: string;
26	}
27	
28	interface ResendWebhookEvent {
29		type: string;
30		created_at: string;
31		data: {
32			email_id: string;
33			from: string;
34			to: string[];
35			subject: string;
36			created_at: string;
37			message_id: string;
38			bcc: string[];
39			cc: string[];
40			attachments: ResendAttachmentMetadata[];
41		};
42	}
43	
44	interface ResendEmail {
45		email_id: string;
46		from: string;
47		to: string[];
48		subject: string;
49		html: string | null;
50		text: string | null;
51		headers: Record<string, string>;
52	}
53	
54	interface ResendAttachment {
55		filename: string;
56		content_type: string;
57		size: number;
58		download_url: string;
59		expires_at: string;
60		// Present on the download-URL response; used to skip inline attachments.
61		content_id?: string;
62		content_disposition?: string;
63	}
64	
65	/** Service-role client used to bypass RLS for webhook-driven inserts. */
66	function createServiceClient(url: string, key: string) {
67		return createClient(url, key, {
68			auth: { autoRefreshToken: false, persistSession: false }
69		});
70	}
71	
72	/** The Supabase client this function threads through its helpers. */
73	type SupabaseClient = ReturnType<typeof createServiceClient>;
74	
75	/** The receipt row insert helpers return (only these fields are read). */
76	interface InsertedReceipt {
77		id?: string;
78		merchant_name?: string | null;
79		total_amount?: number | null;
80		[key: string]: unknown;
81	}
82	
83	function jsonResponse(status: number, body: unknown): Response {
84		return new Response(JSON.stringify(body), {
85			status,
86			headers: { 'Content-Type': 'application/json' }
87		});
88	}
89	
90	/**
91	 * Verifies the Resend webhook signature using Svix library
92	 * Based on: https://resend.com/docs/dashboard/webhooks/verify-webhooks-requests
93	 */
94	function verifyWebhookSignature(headers: Headers, payload: string, signingSecret: string): boolean {
95		const svixId = headers.get('svix-id');
96		const svixTimestamp = headers.get('svix-timestamp');
97		const svixSignature = headers.get('svix-signature');
98	
99		console.log('Signature verification headers:', {
100			hasSignature: !!svixSignature,
101			hasTimestamp: !!svixTimestamp,
102			hasId: !!svixId
103		});
104	
105		if (!svixId || !svixTimestamp || !svixSignature) {
106			console.error('Missing webhook signature headers:', {
107				signature: svixSignature ? 'present' : 'missing',
108				timestamp: svixTimestamp ? 'present' : 'missing',
109				id: svixId ? 'present' : 'missing'
110			});
111			return false;
112		}
113	
114		try {
115			const wh = new Webhook(signingSecret);
116	
117			// Verify the webhook - this will throw on error
118			wh.verify(payload, {
119				'svix-id': svixId,
120				'svix-timestamp': svixTimestamp,
121				'svix-signature': svixSignature
122			});
123	
124			console.log('Webhook signature verified successfully');
125			return true;
126		} catch (err) {
127			console.error('Webhook signature verification failed:', err);
128			return false;
129		}
130	}
131	
132	async function uploadToStorage(
133		supabase: SupabaseClient,
134		userId: string,
135		bytes: Uint8Array,
136		contentType: string,
137		ext: string
138	): Promise<{ path: string; signedUrl: string }> {
139		const path = `${userId}/${crypto.randomUUID()}.${ext}`;
140		const { error } = await supabase.storage
141			.from('receipts')
142			.upload(path, bytes, { contentType, upsert: false });
143		if (error) throw error;
144		// #{#sec1b} Use signed URL — receipts bucket is private (#{#sec1a})
145		// 5-minute expiry matches OCR signed URL pattern in ReceiptService.ts
146		const { data, error: signError } = await supabase.storage
147			.from('receipts')
148			.createSignedUrl(path, 300);
149		if (signError) throw signError;
150		return { path, signedUrl: data.signedUrl };
151	}
152	
153	// #{#fcr1a} #{#fcr2a} Best-effort exchange rate lookup for foreign currency receipts.
154	// Returns null if currency is CAD/unknown, date is missing, or the API call fails —
155	// matches ReceiptService.uploadAndCreate so the receipt still saves without a rate.
156	async function fetchRateForReceipt(
157		currency: string | null | undefined,
158		transactionDate: string | null | undefined
159	): Promise<number | null> {
160		if (!currency || currency === 'CAD' || !transactionDate) return null;
161		try {
162			return await fetchExchangeRate(currency, transactionDate);
163		} catch (err) {
164			console.error('Exchange rate fetch failed:', err);
165			return null;
166		}
167	}
168	
169	async function insertReceipt(
170		supabase: SupabaseClient,
171		receiptData: Record<string, unknown>
172	): Promise<InsertedReceipt | null> {
173		console.log('Attempting to insert receipt with RPC...');
174		// Use RPC to insert with proper user context
175		const { data, error } = await supabase.rpc('insert_receipt_with_context', {
176			receipt_data: receiptData
177		});
178	
179		if (error) {
180			console.error('RPC insert failed:', JSON.stringify(error, null, 2));
181			console.log('Falling back to direct insert...');
182	
183			// Fallback to direct insert - bypass RLS with service role
184			const { data: directData, error: directError } = await supabase
185				.from('receipts')
186				.insert(receiptData)
187				.select('*')
188				.single();
189	
190			if (directError) {
191				console.error('Direct insert also failed:', JSON.stringify(directError, null, 2));
192				throw directError;
193			}
194			console.log('Direct insert succeeded');
195			return directData;
196		}
197	
198		console.log('RPC insert succeeded');
199		return data;
200	}
