// Deno Deploy / Supabase Edge Function for Resend webhook
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { Webhook } from 'https://esm.sh/svix@1.15.0';
import { ocrFromUrl, processEmailText, textToImage } from '../_shared/mistral.ts';
import { resolveOcrReceiptDate } from '../_shared/receiptDateCorrection.ts';
import { fetchExchangeRate } from '../_shared/exchangeRate.ts';
import {
	isSupportedReceiptType,
	isInlineAttachment,
	hasUsableOcrData,
	hasSupportedAttachments
} from '../_shared/attachmentFiltering.ts';
import {
	sendNotificationEmail as sendResendNotification,
	type NotificationType
} from '../_shared/notify.ts';
import { parseSenderEmail } from '../_shared/emailParsing.ts';
import { errText } from '../_shared/errText.ts';

interface ResendAttachmentMetadata {
	id: string;
	filename: string;
	content_type: string;
	content_disposition?: string;
	content_id?: string;
}

interface ResendWebhookEvent {
	type: string;
	created_at: string;
	data: {
		email_id: string;
		from: string;
		to: string[];
		subject: string;
		created_at: string;
		message_id: string;
		bcc: string[];
		cc: string[];
		attachments: ResendAttachmentMetadata[];
	};
}

interface ResendEmail {
	email_id: string;
	from: string;
	to: string[];
	subject: string;
	html: string | null;
	text: string | null;
	headers: Record<string, string>;
}

interface ResendAttachment {
	filename: string;
	content_type: string;
	size: number;
	download_url: string;
	expires_at: string;
	// Present on the download-URL response; used to skip inline attachments.
	content_id?: string;
	content_disposition?: string;
}

/** Service-role client used to bypass RLS for webhook-driven inserts. */
function createServiceClient(url: string, key: string) {
	return createClient(url, key, {
		auth: { autoRefreshToken: false, persistSession: false }
	});
}

/** The Supabase client this function threads through its helpers. */
type SupabaseClient = ReturnType<typeof createServiceClient>;

/** The receipt row insert helpers return (only these fields are read). */
interface InsertedReceipt {
	id?: string;
	merchant_name?: string | null;
	total_amount?: number | null;
	[key: string]: unknown;
}

function jsonResponse(status: number, body: unknown): Response {
	return new Response(JSON.stringify(body), {
		status,
		headers: { 'Content-Type': 'application/json' }
	});
}

/**
 * Verifies the Resend webhook signature using Svix library
 * Based on: https://resend.com/docs/dashboard/webhooks/verify-webhooks-requests
 */
function verifyWebhookSignature(headers: Headers, payload: string, signingSecret: string): boolean {
	const svixId = headers.get('svix-id');
	const svixTimestamp = headers.get('svix-timestamp');
	const svixSignature = headers.get('svix-signature');

	console.log('Signature verification headers:', {
		hasSignature: !!svixSignature,
		hasTimestamp: !!svixTimestamp,
		hasId: !!svixId
	});

	if (!svixId || !svixTimestamp || !svixSignature) {
		console.error('Missing webhook signature headers:', {
			signature: svixSignature ? 'present' : 'missing',
			timestamp: svixTimestamp ? 'present' : 'missing',
			id: svixId ? 'present' : 'missing'
		});
		return false;
	}

	try {
		const wh = new Webhook(signingSecret);

		// Verify the webhook - this will throw on error
		wh.verify(payload, {
			'svix-id': svixId,
			'svix-timestamp': svixTimestamp,
			'svix-signature': svixSignature
		});

		console.log('Webhook signature verified successfully');
		return true;
	} catch (err) {
		console.error('Webhook signature verification failed:', err);
		return false;
	}
}

async function uploadToStorage(
	supabase: SupabaseClient,
	userId: string,
	bytes: Uint8Array,
	contentType: string,
	ext: string
): Promise<{ path: string; signedUrl: string }> {
	const path = `${userId}/${crypto.randomUUID()}.${ext}`;
	const { error } = await supabase.storage
		.from('receipts')
		.upload(path, bytes, { contentType, upsert: false });
	if (error) throw error;
	// #{#sec1b} Use signed URL — receipts bucket is private (#{#sec1a})
	// 5-minute expiry matches OCR signed URL pattern in ReceiptService.ts
	const { data, error: signError } = await supabase.storage
		.from('receipts')
		.createSignedUrl(path, 300);
	if (signError) throw signError;
	return { path, signedUrl: data.signedUrl };
}

// #{#fcr1a} #{#fcr2a} Best-effort exchange rate lookup for foreign currency receipts.
// Returns null if currency is CAD/unknown, date is missing, or the API call fails —
// matches ReceiptService.uploadAndCreate so the receipt still saves without a rate.
async function fetchRateForReceipt(
	currency: string | null | undefined,
	transactionDate: string | null | undefined
): Promise<number | null> {
	if (!currency || currency === 'CAD' || !transactionDate) return null;
	try {
		return await fetchExchangeRate(currency, transactionDate);
	} catch (err) {
		console.error('Exchange rate fetch failed:', err);
		return null;
	}
}

async function insertReceipt(
	supabase: SupabaseClient,
	receiptData: Record<string, unknown>
): Promise<InsertedReceipt | null> {
	console.log('Attempting to insert receipt with RPC...');
	// Use RPC to insert with proper user context
	const { data, error } = await supabase.rpc('insert_receipt_with_context', {
		receipt_data: receiptData
	});

	if (error) {
		console.error('RPC insert failed:', JSON.stringify(error, null, 2));
		console.log('Falling back to direct insert...');

		// Fallback to direct insert - bypass RLS with service role
		const { data: directData, error: directError } = await supabase
			.from('receipts')
			.insert(receiptData)
			.select('*')
			.single();

		if (directError) {
			console.error('Direct insert also failed:', JSON.stringify(directError, null, 2));
			throw directError;
		}
		console.log('Direct insert succeeded');
		return directData;
	}

	console.log('RPC insert succeeded');
	return data;
}

/**
 * Persist a failed notification send so the failure is not silent.
 *
 * The notification channel (email) is the thing that broke, so we can't email
 * the user to tell them email failed. Instead we record it in
 * `email_send_failures`: the row is family-scoped (RLS) so the user sees an
 * in-app notice, and it doubles as the admin alert feed. Best-effort — a
 * logging failure must never break webhook processing.
 */
async function recordNotificationFailure(
	supabase: SupabaseClient,
	params: {
		userId: string;
		recipient: string;
		notificationType: NotificationType;
		originalSubject: string;
		emailId?: string;
		statusCode: number;
		error: string;
	}
): Promise<void> {
	try {
		const { error } = await supabase.from('email_send_failures').insert({
			user_id: params.userId,
			recipient: params.recipient,
			notification_type: params.notificationType,
			original_subject: params.originalSubject,
			resend_email_id: params.emailId ?? null,
			status_code: params.statusCode,
			error: params.error
		});
		if (error) {
			console.error('Failed to record notification failure:', JSON.stringify(error));
		} else {
			console.log(`Recorded notification failure for ${params.recipient} (admin alert queued)`);
		}
	} catch (err) {
		console.error('Exception recording notification failure:', err);
	}
}

/**
 * Send a notification email and, if the send fails, record it durably so the
 * failure surfaces to the user (in-app) and to admins instead of vanishing into
 * the logs. Wraps the extracted `sendResendNotification` sender.
 */
async function sendNotificationEmail(
	supabase: SupabaseClient,
	userId: string,
	apiKey: string,
	toEmail: string,
	notificationType: NotificationType,
	title: string,
	message: string,
	originalSubject: string,
	emailId?: string
): Promise<void> {
	const result = await sendResendNotification(
		apiKey,
		toEmail,
		notificationType,
		title,
		message,
		originalSubject,
		emailId
	);

	if (!result.ok) {
		await recordNotificationFailure(supabase, {
			userId,
			recipient: toEmail,
			notificationType,
			originalSubject,
			emailId,
			statusCode: result.status,
			error: result.error ?? 'Unknown send failure'
		});
	}
}

Deno.serve(async (req) => {
	console.log('=== Resend Webhook Request Received ===');
	console.log('Method:', req.method);
	console.log('URL:', req.url);

	if (req.method !== 'POST') {
		console.log('Rejecting non-POST request');
		return jsonResponse(405, { error: 'Method not allowed' });
	}

	// Read the raw body for signature verification
	const bodyText = await req.text();
	console.log('Received webhook payload length:', bodyText.length);
	console.log('Raw payload:', bodyText.substring(0, 500) + (bodyText.length > 500 ? '...' : ''));

	let event: ResendWebhookEvent;

	try {
		event = JSON.parse(bodyText);
		console.log('Parsed event type:', event.type);
		console.log('Event data:', JSON.stringify(event.data));
	} catch (e) {
		console.error('Failed to parse JSON:', e);
		return jsonResponse(400, { error: 'Invalid JSON' });
	}

	// Basic validation
	if (!event.type) {
		console.error('Missing event type in payload');
		return jsonResponse(400, { error: 'Missing event type' });
	}

	const supabaseUrl = Deno.env.get('SUPABASE_URL');
	const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
	const resendApiKey = Deno.env.get('RESEND_API_KEY');
	const resendWebhookSecret = Deno.env.get('RESEND_WEBHOOK_SECRET');

	if (!supabaseUrl || !serviceRoleKey) {
		return jsonResponse(500, { error: 'Missing Supabase env' });
	}
	if (!resendApiKey) {
		console.error('RESEND_API_KEY environment variable is not set');
		return jsonResponse(500, { error: 'Missing Resend API key' });
	}

	console.log(`Resend API key is set (length: ${resendApiKey.length})`);

	// Log all request headers for debugging
	console.log('Request headers:', JSON.stringify(Object.fromEntries(req.headers.entries())));

	// Verify the webhook signature — FAIL CLOSED. This endpoint runs with the
	// service role and inserts receipts keyed on the sender's email, so an
	// unauthenticated caller could forge an `email.received` event and inject
	// receipts into any user's account (bypassing RLS). A missing secret is a
	// server misconfiguration (500); a bad/absent signature is rejected (401).
	// Never log the secret value.
	if (!resendWebhookSecret) {
		console.error('RESEND_WEBHOOK_SECRET is not set — refusing to process unverified webhook');
		return jsonResponse(500, { error: 'Webhook signing secret not configured' });
	}
	if (!verifyWebhookSignature(req.headers, bodyText, resendWebhookSecret)) {
		console.error('Invalid webhook signature — rejecting request');
		return jsonResponse(401, { error: 'Invalid webhook signature' });
	}
	console.log('Webhook signature verification passed');

	// Only process email.received events
	if (event.type !== 'email.received') {
		console.log(`Ignoring event type: ${event.type} - returning success`);
		return jsonResponse(200, { message: `Event type ${event.type} ignored` });
	}

	console.log('Processing email.received event...');

	const supabase = createServiceClient(supabaseUrl, serviceRoleKey);

	// Find user by sender email. Resend delivers `from` as either a bare address
	// or `Display Name <addr>` — extract the address so the exact-match lookup
	// works regardless of the forwarding client's formatting.
	const sender = parseSenderEmail(event.data?.from);
	if (!sender) {
		console.error('Missing or unparseable sender in event data:', event.data?.from);
		return jsonResponse(400, { error: 'Missing sender' });
	}

	console.log(`Looking up user by email: ${sender}`);
	const { data: userIdData, error: userErr } = await supabase.rpc('find_user_by_email', {
		email_address: sender
	});
	if (userErr) {
		console.error(`Error finding user: ${JSON.stringify(userErr)}`);
		return jsonResponse(500, { error: userErr.message });
	}
	if (!userIdData) {
		console.error(`No user found for email: ${sender}`);
		return jsonResponse(404, { error: 'User not found for sender email' });
	}
	const userId = userIdData as string;
	console.log(`Found user ID: ${userId}`);

	// Fetch the full email content from Resend API to get body text
	console.log(`Fetching email content for email_id: ${event.data.email_id}`);
	console.log(
		`Using API key: ${resendApiKey.substring(0, 7)}...${resendApiKey.substring(resendApiKey.length - 4)}`
	);
	console.log(`API endpoint: https://api.resend.com/emails/receiving/${event.data.email_id}`);

	let emailBodyText = '';

	try {
		const emailResponse = await fetch(
			`https://api.resend.com/emails/receiving/${event.data.email_id}`,
			{
				method: 'GET',
				headers: {
					Authorization: `Bearer ${resendApiKey}`,
					'Content-Type': 'application/json'
				}
			}
		);

		console.log(`Email fetch response status: ${emailResponse.status}`);

		if (!emailResponse.ok) {
			const errorText = await emailResponse.text();
			console.error(`Failed to fetch email: ${emailResponse.status} ${emailResponse.statusText}`);
			console.error(`Error response body: ${errorText}`);
			// Don't return error - continue with attachments processing
		} else {
			const email: ResendEmail = await emailResponse.json();
			console.log(
				`Email fetched successfully. Has text: ${!!email.text}, Has html: ${!!email.html}`
			);
			emailBodyText = (email.text || email.html || '').toString();
		}
	} catch (e) {
		console.error('Exception fetching email content:', e);
		// Continue processing - we can still try attachments
	}

	// #{#eaf5a} Check for supported attachments before processing body text
	const attachmentMetadata = event.data.attachments || [];
	const hasScannable = hasSupportedAttachments(attachmentMetadata);

	let inserted: InsertedReceipt | null = null;
	const processingErrors: string[] = [];

	// #{#eaf5a} Only process body text if no supported attachments exist
	if (emailBodyText && !hasScannable) {
		console.log('No supported attachments found, processing email body text');
	} else if (hasScannable) {
		console.log(
			`Skipping body text extraction — ${attachmentMetadata.length} supported attachment(s) found`
		);
	}

	if (emailBodyText && !hasScannable) {
		try {
			console.log('Processing email body text with Mistral...');
			const extracted = await processEmailText(emailBodyText);

			if (extracted) {
				console.log('Mistral found receipt data:', JSON.stringify(extracted, null, 2));

				// Convert the text to an image
				console.log('Converting text to image...');
				const imageBytes = await textToImage(emailBodyText);
				const { path, signedUrl } = await uploadToStorage(
					supabase,
					userId,
					imageBytes,
					'image/svg+xml',
					'svg'
				);
				console.log('Image uploaded to:', signedUrl);

				// Insert receipt with the text-as-image
				try {
					console.log('Inserting receipt for user:', userId);

					// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then
					// flag suspicious dates (#{#dtv4a}). Uncorrectable wrong-token reads are flagged.
					const resolved = resolveOcrReceiptDate(
						extracted.transaction_date ?? null,
						extracted.raw_date_text ?? null,
						new Date()
					);
					extracted.transaction_date = resolved.transaction_date;
					const suspicious = resolved.suspicious_date;
					if (suspicious) {
						console.log(
							`Warning: Suspicious date detected for email receipt: ${extracted.transaction_date}`
						);

						// Notify user about suspicious date
						await sendNotificationEmail(
							supabase,
							userId,
							resendApiKey,
							sender,
							'warning',
							'Please Check Receipt Date',
							`The receipt date we found (${extracted.transaction_date}) seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
							event.data.subject,
							event.data.email_id
						);
					}

					// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
					const exchangeRate = await fetchRateForReceipt(
						extracted.currency,
						extracted.transaction_date
					);

					inserted = await insertReceipt(supabase, {
						user_id: userId,
						receipt_image_path: path,
						merchant_name: extracted.merchant_name,
						total_amount: extracted.total_amount,
						tax: extracted.tax,
						transaction_date: extracted.transaction_date,
						currency: extracted.currency,
						exchange_rate_to_cad: exchangeRate,
						credit_card_name: extracted.credit_card_name,
						credit_card_last_4: extracted.credit_card_last_4,
						suspicious_date: suspicious
					});
					console.log('Receipt inserted successfully:', inserted?.id);
				} catch (insertErr) {
					const msg = `Body text insert failed: ${errText(insertErr)}`;
					console.error(msg);
					processingErrors.push(msg);
				}
			} else {
				console.log('No receipt data found in email body text');
				// Don't send notification yet - we'll try attachments first
			}
		} catch (e) {
			const msg = `Body text processing error: ${errText(e)}`;
			console.error(msg);
			processingErrors.push(msg);
		}
	}

	// Process attachments (either as primary path or fallback from body text)
	if (!inserted) {
		console.log(`Found ${attachmentMetadata.length} attachment(s) in webhook payload`);

		if (attachmentMetadata.length === 0) {
			console.log('No attachments to process');
		} else {
			// Fetch attachment download URLs from Resend API
			console.log(`Fetching attachment download URLs for email_id: ${event.data.email_id}`);

			try {
				const attachmentsResponse = await fetch(
					`https://api.resend.com/emails/receiving/${event.data.email_id}/attachments`,
					{
						method: 'GET',
						headers: {
							Authorization: `Bearer ${resendApiKey}`,
							'Content-Type': 'application/json'
						}
					}
				);

				console.log(`Attachments fetch response status: ${attachmentsResponse.status}`);

				if (!attachmentsResponse.ok) {
					const errorText = await attachmentsResponse.text();
					const msg = `Resend attachment fetch failed: ${attachmentsResponse.status} ${attachmentsResponse.statusText} — ${errorText}`;
					console.error(msg);
					processingErrors.push(msg);
				} else {
					const attachmentsData = await attachmentsResponse.json();
					console.log(`Attachments response data: ${JSON.stringify(attachmentsData)}`);
					const attachments: ResendAttachment[] = attachmentsData.data || [];

					console.log(`Received ${attachments.length} attachment download URL(s)`);

					let processedCount = 0;

					for (const att of attachments) {
						try {
							// #{#eaf2a} Skip inline attachments (signatures, logos)
							if (
								isInlineAttachment({
									filename: att.filename,
									content_type: att.content_type,
									content_id: att.content_id,
									content_disposition: att.content_disposition
								})
							) {
								console.log(
									`Skipping inline attachment: ${att.filename} (content_id: ${att.content_id})`
								);
								continue;
							}

							// #{#eaf1a} Filter by supported MIME types
							const ct = att.content_type || 'application/octet-stream';
							if (!isSupportedReceiptType(ct, att.filename)) {
								console.log(`Skipping unsupported attachment type: ${ct} (${att.filename})`);
								continue;
							}

							console.log(`Processing attachment: ${att.filename}`);

							// Download attachment using the provided download_url
							const downloadResponse = await fetch(att.download_url);
							if (!downloadResponse.ok) {
								const msg = `Download failed for ${att.filename}: HTTP ${downloadResponse.status}`;
								console.error(msg);
								processingErrors.push(msg);

								// Notify user about attachment download failure
								await sendNotificationEmail(
									supabase,
									userId,
									resendApiKey,
									sender,
									'error',
									'Attachment Download Failed',
									`We couldn't download the attachment "${att.filename}" from your email. Resend attachments expire after 30 minutes, so the download link may have expired. Please try forwarding the email again.`,
									event.data.subject,
									event.data.email_id
								);

								continue;
							}

							const bytes = new Uint8Array(await downloadResponse.arrayBuffer());
							const ext = (att.filename?.split('.')?.pop() || 'bin').toLowerCase();

							const { path, signedUrl } = await uploadToStorage(supabase, userId, bytes, ct, ext);
							const extracted = await ocrFromUrl(signedUrl, ct).catch(async (err) => {
								const msg = `OCR failed for ${att.filename}: ${err?.message || err}`;
								console.error(msg);
								processingErrors.push(msg);

								// Notify user about OCR failure
								await sendNotificationEmail(
									supabase,
									userId,
									resendApiKey,
									sender,
									'error',
									'Receipt Reading Failed',
									`We couldn't extract receipt information from "${att.filename}". The image or PDF may be unclear, too dark, or rotated. Please try sending a clearer, well-lit photo of the receipt.`,
									event.data.subject,
									event.data.email_id
								);

								return null;
							});

							// #{#eaf3a} Validate OCR results before inserting
							if (!extracted || !hasUsableOcrData(extracted)) {
								const msg = `OCR returned no usable data for: ${att.filename} (merchant: ${extracted?.merchant_name ?? 'null'}, amount: ${extracted?.total_amount ?? 'null'})`;
								console.log(msg);
								processingErrors.push(msg);
								continue;
							}

							console.log('Inserting receipt from attachment for user:', userId);

							// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then
							// flag suspicious dates (#{#dtv4a}). Uncorrectable wrong-token reads are flagged.
							const resolved = resolveOcrReceiptDate(
								extracted.transaction_date ?? null,
								extracted.raw_date_text ?? null,
								new Date()
							);
							extracted.transaction_date = resolved.transaction_date;
							const suspicious = resolved.suspicious_date;
							if (suspicious) {
								console.log(
									`Warning: Suspicious date detected for email attachment receipt: ${extracted.transaction_date}`
								);

								// Notify user about suspicious date
								await sendNotificationEmail(
									supabase,
									userId,
									resendApiKey,
									sender,
									'warning',
									'Please Check Receipt Date',
									`The receipt date we found (${extracted.transaction_date}) from "${att.filename}" seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
									event.data.subject,
									event.data.email_id
								);
							}

							// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
							const exchangeRate = await fetchRateForReceipt(
								extracted.currency,
								extracted.transaction_date
							);

							inserted = await insertReceipt(supabase, {
								user_id: userId,
								receipt_image_path: path,
								transaction_date: extracted.transaction_date,
								total_amount: extracted.total_amount,
								tax: extracted.tax,
								merchant_name: extracted.merchant_name,
								currency: extracted.currency,
								exchange_rate_to_cad: exchangeRate,
								credit_card_name: extracted.credit_card_name,
								credit_card_last_4: extracted.credit_card_last_4,
								suspicious_date: suspicious
							});
							processedCount++;
							console.log('Receipt from attachment inserted successfully');
							// #{#eaf4a} No break — continue processing remaining attachments
						} catch (e) {
							const msg = `Attachment error (${att.filename}): ${errText(e)}`;
							console.error(msg);
							processingErrors.push(msg);
						}
					}

					console.log(
						`Processed ${processedCount} receipt(s) from ${attachments.length} attachment(s)`
					);
				}
			} catch (e) {
				const msg = `Exception fetching attachment URLs: ${errText(e)}`;
				console.error(msg);
				processingErrors.push(msg);
			}
		}
	}

	// #{#eaf5a} Fallback: if attachments were prioritized but none produced a receipt,
	// try body text extraction as a last resort
	if (!inserted && hasScannable && emailBodyText) {
		console.log('No receipts from attachments, falling back to email body text');
		try {
			const extracted = await processEmailText(emailBodyText);

			if (extracted) {
				console.log(
					'Mistral found receipt data in body text (fallback):',
					JSON.stringify(extracted, null, 2)
				);

				const imageBytes = await textToImage(emailBodyText);
				const { path } = await uploadToStorage(
					supabase,
					userId,
					imageBytes,
					'image/svg+xml',
					'svg'
				);

				// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then flag.
				const resolved = resolveOcrReceiptDate(
					extracted.transaction_date ?? null,
					extracted.raw_date_text ?? null,
					new Date()
				);
				extracted.transaction_date = resolved.transaction_date;
				const suspicious = resolved.suspicious_date;
				if (suspicious) {
					console.log(
						`Warning: Suspicious date detected for email receipt (fallback): ${extracted.transaction_date}`
					);

					await sendNotificationEmail(
						supabase,
						userId,
						resendApiKey,
						sender,
						'warning',
						'Please Check Receipt Date',
						`The receipt date we found (${extracted.transaction_date}) seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
						event.data.subject,
						event.data.email_id
					);
				}

				// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
				const exchangeRate = await fetchRateForReceipt(
					extracted.currency,
					extracted.transaction_date
				);

				inserted = await insertReceipt(supabase, {
					user_id: userId,
					receipt_image_path: path,
					merchant_name: extracted.merchant_name,
					total_amount: extracted.total_amount,
					tax: extracted.tax,
					transaction_date: extracted.transaction_date,
					currency: extracted.currency,
					exchange_rate_to_cad: exchangeRate,
					credit_card_name: extracted.credit_card_name,
					credit_card_last_4: extracted.credit_card_last_4,
					suspicious_date: suspicious
				});
				console.log('Receipt inserted from body text (fallback):', inserted?.id);
			}
		} catch (e) {
			const msg = `Body text fallback error: ${errText(e)}`;
			console.error(msg);
			processingErrors.push(msg);
		}
	}

	if (!inserted) {
		// No receipt was found in email body or attachments - notify user
		await sendNotificationEmail(
			supabase,
			userId,
			resendApiKey,
			sender,
			'error',
			'No Receipt Found',
			`We couldn't find any receipt information in your email or attachments. Please make sure you're forwarding a clear receipt photo or PDF. If you're forwarding text-only emails, they may not contain receipt data we can extract.`,
			event.data.subject,
			event.data.email_id
		);

		console.error('Processing failed. Errors:', JSON.stringify(processingErrors));
		return jsonResponse(422, {
			error: 'No valid receipt found in email body or attachments',
			details: processingErrors,
			email_id: event.data.email_id,
			attachments_count: attachmentMetadata.length,
			had_body_text: !!emailBodyText,
			had_scannable_attachments: hasScannable
		});
	}

	// Success! Send confirmation email
	const merchantInfo = inserted.merchant_name ? ` from ${inserted.merchant_name}` : '';
	const amountInfo = inserted.total_amount ? ` for $${inserted.total_amount}` : '';

	await sendNotificationEmail(
		supabase,
		userId,
		resendApiKey,
		sender,
		'success',
		'Receipt Added Successfully',
		`Your receipt${merchantInfo}${amountInfo} has been added to your expense tracker. You can view and edit it at any time in your receipts page.`,
		event.data.subject,
		event.data.email_id
	);

	return jsonResponse(200, { ok: true, receipt: inserted });
});

