/**
 * Shared Receipt Date Parsing Correction (Edge Function copy)
 *
 * #{#rdc4c authority=developer} - Correction parity for the email/resend path
 *
 * Behavioural mirror of `src/lib/utils/receiptDateCorrection.ts`. Kept in lock-step with
 * that file; `receiptDateCorrection.spec.ts` asserts parity over the regression corpus so
 * the two copies cannot drift. Self-contained (inline local-date helpers) so it has no
 * dependency on the SvelteKit `$lib` aliases.
 *
 * Implements #{#rdc1a}, #{#rdc3a}, #{#rdc3b}, #{#rdc4a}, #{#rdc4b}, #{#rdc5a}.
 */

import { isSuspiciousDate } from './dateValidation.ts';

export const PLAUSIBILITY_WINDOW_DAYS = 90;

const MS_PER_DAY = 1000 * 60 * 60 * 24;

export type DateCorrectionResult = {
	transaction_date: string | null;
	corrected: boolean;
	uncorrectable: boolean;
};

/** Parse a YYYY-MM-DD string into a local-time Date (avoids UTC day shift). */
function toDate(iso: string | null | undefined): Date | undefined {
	if (!iso) return undefined;
	const parts = iso.split('-');
	if (parts.length !== 3) return undefined;
	const [y, m, d] = parts.map((p) => parseInt(p, 10));
	if (Number.isNaN(y) || Number.isNaN(m) || Number.isNaN(d)) return undefined;
	return new Date(y, m - 1, d);
}

/** Format a Date as a local-time YYYY-MM-DD string. */
function toISODateString(date: Date): string {
	const y = date.getFullYear();
	const m = String(date.getMonth() + 1).padStart(2, '0');
	const d = String(date.getDate()).padStart(2, '0');
	return `${y}-${m}-${d}`;
}

/** Calendar-day difference (uploadDate - candidate), DST-safe via UTC-normalized parts. */
function dayDelta(candidate: Date, uploadDate: Date): number {
	const utcDay = (dt: Date) => Date.UTC(dt.getFullYear(), dt.getMonth(), dt.getDate());
	return Math.round((utcDay(uploadDate) - utcDay(candidate)) / MS_PER_DAY);
}

export function isPlausible(candidate: Date, uploadDate: Date): boolean {
	const diffDays = dayDelta(candidate, uploadDate);
	return diffDays >= 0 && diffDays <= PLAUSIBILITY_WINDOW_DAYS;
}

function expandYear(token: string): number | null {
	if (token.length === 4) return parseInt(token, 10);
	if (token.length >= 1 && token.length <= 2) return 2000 + parseInt(token, 10);
	return null;
}

function buildDate(year: number | null, month: number, day: number): string | null {
	if (year === null || !Number.isFinite(month) || !Number.isFinite(day)) return null;
	const date = new Date(year, month - 1, day);
	if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
		return null;
	}
	return toISODateString(date);
}

export function parseRawDate(rawDateText: string, uploadDate: Date): string[] {
	const groups = rawDateText.split(/\D+/).filter((g) => g.length > 0);
	if (groups.length < 3) return [];

	const [a, b, c] = groups;
	const ai = parseInt(a, 10);
	const bi = parseInt(b, 10);
	const ci = parseInt(c, 10);

	const interpretations: Array<string | null> = [
		a.length === 4 ? buildDate(parseInt(a, 10), bi, ci) : null, // YYYY/MM/DD
		buildDate(expandYear(a), bi, ci), // YY/MM/DD (and YY-MM-DD)
		buildDate(expandYear(c), ai, bi), // MM/DD/YY
		buildDate(expandYear(c), bi, ai) // DD/MM/YY
	];

	const seen = new Map<string, number>();
	interpretations.forEach((iso, rank) => {
		if (!iso) return;
		const date = toDate(iso);
		if (!date || !isPlausible(date, uploadDate)) return;
		if (!seen.has(iso)) seen.set(iso, rank);
	});

	return [...seen.entries()]
		.sort((x, y) => {
			const dx = dayDelta(toDate(x[0]) as Date, uploadDate);
			const dy = dayDelta(toDate(y[0]) as Date, uploadDate);
			if (dx !== dy) return dx - dy;
			return x[1] - y[1];
		})
		.map((entry) => entry[0]);
}

export function correctDate(
	transactionDate: string | null,
	rawDateText: string | null | undefined,
	uploadDate: Date
): DateCorrectionResult {
	const mistralDate = transactionDate && transactionDate.length > 0 ? transactionDate : null;

	if (mistralDate) {
		const parsed = toDate(mistralDate);
		if (parsed && isPlausible(parsed, uploadDate)) {
			return { transaction_date: mistralDate, corrected: false, uncorrectable: false };
		}
	}

	const raw = rawDateText && rawDateText.trim().length > 0 ? rawDateText.trim() : null;
	if (!raw) {
		return { transaction_date: mistralDate, corrected: false, uncorrectable: false };
	}

	const candidates = parseRawDate(raw, uploadDate);
	if (candidates.length > 0) {
		return { transaction_date: candidates[0], corrected: true, uncorrectable: false };
	}

	return { transaction_date: mistralDate, corrected: false, uncorrectable: mistralDate !== null };
}

export function resolveOcrReceiptDate(
	transactionDate: string | null,
	rawDateText: string | null | undefined,
	uploadDate: Date
): { transaction_date: string | null; suspicious_date: boolean } {
	const { transaction_date, uncorrectable } = correctDate(transactionDate, rawDateText, uploadDate);
	return {
		transaction_date,
		suspicious_date: uncorrectable || isSuspiciousDate(transaction_date)
	};
}

