1	// Parsing helpers for inbound email metadata from the Resend webhook.
2	
3	/**
4	 * Extract the bare email address from a mail `from` / sender value.
5	 *
6	 * Resend delivers `from` either as a bare address (`a@b.com`) or in RFC 5322
7	 * display-name form (`Name <a@b.com>`, and often quoted: `"Last, First" <a@b.com>`).
8	 * `find_user_by_email` does an exact match on the address, so the display name
9	 * and angle brackets must be stripped — otherwise a legitimately registered user
10	 * who forwards from a client that includes their display name gets a spurious
11	 * "User not found".
12	 *
13	 * Returns the lowercased address, or null when no usable address is present
14	 * (empty input, or a value that doesn't look like an email after extraction).
15	 */
16	export function parseSenderEmail(from: string | null | undefined): string | null {
17		if (!from) return null;
18	
19		let candidate = from.trim();
20	
21		// Prefer the address inside angle brackets. Use the LAST `<...>` group: a
22		// display name can itself contain stray brackets, but the real address is the
23		// final angle-bracket pair (e.g. `"<weird> Name" <a@b.com>`).
24		const angleGroups = candidate.match(/<([^<>]*)>/g);
25		if (angleGroups && angleGroups.length > 0) {
26			const last = angleGroups[angleGroups.length - 1];
27			candidate = last.slice(1, -1).trim();
28		}
29	
30		candidate = candidate.toLowerCase();
31	
