/**
 * Test Suite for the Edge Function copy of receipt date correction.
 *
 * #{#rdc4c} - Correction parity for the email/resend path
 *
 * Guards the Deno `_shared/receiptDateCorrection.ts` copy against drift from the
 * canonical `src/lib/utils/receiptDateCorrection.ts`. Pure data — no Mistral, no network.
 */

import { describe, it, expect } from 'vitest';
import { correctDate } from './receiptDateCorrection.ts';

const d = (y: number, m: number, day: number) => new Date(y, m - 1, day);

describe('#{#rdc4c} - Edge-function correctDate copy', () => {
	it('corrects a format-misread two-digit year (No Frills / Loblaws)', () => {
		expect(correctDate('2005-06-05', '25/06/05', d(2025, 6, 7))).toEqual({
			transaction_date: '2025-06-05',
			corrected: true,
			uncorrectable: false
		});
	});

	it('accepts a plausible Mistral date unchanged (Costco YYYY/MM/DD)', () => {
		expect(correctDate('2025-06-05', '2025/06/05', d(2025, 6, 7))).toEqual({
			transaction_date: '2025-06-05',
			corrected: false,
			uncorrectable: false
		});
	});

	it('flags a wrong-token extraction as uncorrectable (City of Kingston)', () => {
		expect(correctDate('2037-02-11', '2:11:37', d(2025, 6, 7))).toEqual({
			transaction_date: '2037-02-11',
			corrected: false,
			uncorrectable: true
		});
	});

	it('degrades gracefully when the raw field is absent', () => {
		expect(correctDate('2005-06-05', null, d(2025, 6, 7))).toEqual({
			transaction_date: '2005-06-05',
			corrected: false,
			uncorrectable: false
		});
	});
});

