/**
 * Shared Date Validation Utility
 *
 * This utility is used by both:
 * - Frontend (src/lib/utils/dateValidation.ts)
 * - Backend Edge Functions (supabase/functions/resend/index.ts)
 *
 * Implements #{#dtv1a} - Suspicious Date Detection
 */

/**
 * Detects if a receipt date is suspicious (likely OCR misclassification)
 *
 * A date is suspicious if:
 * - It's more than 42 days (6 weeks) in the past
 * - It's in the future
 *
 * @param transactionDate - ISO date string (YYYY-MM-DD) or null
 * @returns true if date is suspicious, false otherwise
 */
export function isSuspiciousDate(transactionDate: string | null): boolean {
	if (!transactionDate) return false; // Missing date not suspicious, just incomplete

	const receiptDate = new Date(transactionDate);
	const today = new Date();

	// Remove time component for accurate day comparison
	receiptDate.setHours(0, 0, 0, 0);
	today.setHours(0, 0, 0, 0);

	const diffMs = today.getTime() - receiptDate.getTime();
	const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

	const SIX_WEEKS_DAYS = 42;

	// Flag if more than 6 weeks old OR in the future
	return diffDays > SIX_WEEKS_DAYS || diffDays < 0;
}

/**
 * Calculates the age of a date in days
 *
 * @param transactionDate - ISO date string (YYYY-MM-DD)
 * @returns Number of days between transaction date and today (negative if future)
 */
export function calculateDateAge(transactionDate: string): number {
	const receiptDate = new Date(transactionDate);
	const today = new Date();

	receiptDate.setHours(0, 0, 0, 0);
	today.setHours(0, 0, 0, 0);

	const diffMs = today.getTime() - receiptDate.getTime();
	return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}
