/**
 * Email receipt date resolution (Edge Function).
 *
 * The Resend webhook has three insert paths (body-text, attachment, and a
 * body-text fallback). They previously each ran `resolveOcrReceiptDate` inline
 * and, when the receipt itself yielded no date, silently inserted a NULL date
 * with no warning to the user (`isSuspiciousDate(null)` is `false`). This module
 * hoists that logic into one handler so every path shares identical null-date
 * behaviour:
 *
 *   1. Use the receipt's own date (OCR / text extraction), corrected and
 *      suspicious-checked exactly as before.
 *   2. If that's null, fall back to the *forwarded email's* original send date —
 *      recovered from the quoted `Date:` / `Sent:` header inside the body. For an
 *      e-receipt this is effectively the purchase date, and it is run through the
 *      same suspicious-window check so a stale forward still gets flagged.
 *   3. If neither yields a date, return `dateSource: 'none'` so the caller can
 *      warn the user instead of dropping the receipt in silently.
 *
 * Note the forwarded date is deliberately parsed only from month-name or ISO
 * forms — never bare numeric `06/07/2026`, which is DD/MM vs MM/DD ambiguous.
 */

import { resolveOcrReceiptDate } from './receiptDateCorrection.ts';

export type EmailReceiptDateSource = 'receipt' | 'forwarded-email' | 'none';

export type EmailReceiptDateResult = {
	transaction_date: string | null;
	suspicious_date: boolean;
	dateSource: EmailReceiptDateSource;
};

const MONTHS: Record<string, number> = {
	jan: 1,
	feb: 2,
	mar: 3,
	apr: 4,
	may: 5,
	jun: 6,
	jul: 7,
	aug: 8,
	sep: 9,
	oct: 10,
	nov: 11,
	dec: 12
};

const MONTH_RE = '(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)';

/** Build a YYYY-MM-DD string, rejecting impossible calendar dates (e.g. Feb 30). */
function buildIso(year: number, month: number, day: number): string | null {
	if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return null;
	if (month < 1 || month > 12 || day < 1 || day > 31) return null;
	// Local-time construction avoids any UTC day-shift; we only read back the parts.
	const date = new Date(year, month - 1, day);
	if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
		return null;
	}
	const m = String(month).padStart(2, '0');
	const d = String(day).padStart(2, '0');
	return `${year}-${m}-${d}`;
}

/**
 * Extract a calendar date from a single mail-header value (the text after
 * `Date:` / `Sent:`). Reads the literal day/month/year tokens only — never the
 * time or timezone — so the sender's local calendar date is preserved without
 * any timezone conversion.
 */
function parseHeaderDateValue(value: string): string | null {
	// ISO 8601 first: "2026-07-06".
	const iso = value.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
	if (iso) return buildIso(Number(iso[1]), Number(iso[2]), Number(iso[3]));

	// "July 6, 2026" / "Jul 6 2026" (month day, year) — Gmail, Apple, Outlook.
	const mdy = value.match(
		new RegExp(`\\b${MONTH_RE}[a-z]*\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?,?\\s+(\\d{4})\\b`, 'i')
	);
	if (mdy) return buildIso(Number(mdy[3]), MONTHS[mdy[1].toLowerCase()], Number(mdy[2]));

	// "6 Jul 2026" (day month year) — RFC 2822 raw Date header.
	const dmy = value.match(
		new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+${MONTH_RE}[a-z]*\\.?,?\\s+(\\d{4})\\b`, 'i')
	);
	if (dmy) return buildIso(Number(dmy[3]), MONTHS[dmy[2].toLowerCase()], Number(dmy[1]));

	return null;
}

/**
 * Recover the original send date of a forwarded email from its body text.
 *
 * When a receipt email is forwarded, mail clients quote the original headers as
 * a `Date:` (Gmail/Apple/RFC) or `Sent:` (Outlook) line. We scan for the first
 * such line that parses to a real calendar date and return it as YYYY-MM-DD.
 * Returns null when the body has no parseable forwarded-header date (e.g. a
 * freshly composed email, or an HTML-only body that hid the headers in markup).
 */
export function extractForwardedDate(body: string | null | undefined): string | null {
	if (!body) return null;
	// Anchor to line start (allowing quote `>` and leading whitespace) so we match
	// the quoted header block, not a stray "…Date:" inside receipt prose.
	const lineRe = /^[ \t>]*(?:date|sent):[ \t]*(.+)$/gim;
	let match: RegExpExecArray | null;
	while ((match = lineRe.exec(body)) !== null) {
		const parsed = parseHeaderDateValue(match[1]);
		if (parsed) return parsed;
	}
	return null;
}

/**
 * The single null-date handler shared by every Resend insert path.
 *
 * `uploadDate` is the reference "now" for the plausibility and suspicious-date
 * windows (passed in rather than read from the clock, so it stays pure/testable).
 */
export function resolveEmailReceiptDate(
	transactionDate: string | null,
	rawDateText: string | null | undefined,
	emailBodyText: string | null | undefined,
	uploadDate: Date
): EmailReceiptDateResult {
	// 1. The receipt's own date wins whenever we have one.
	const fromReceipt = resolveOcrReceiptDate(transactionDate, rawDateText, uploadDate);
	if (fromReceipt.transaction_date) {
		return { ...fromReceipt, dateSource: 'receipt' };
	}

	// 2. Fall back to the forwarded email's date, run through the same checks so a
	//    stale forward (>42 days) is still flagged suspicious.
	const forwarded = extractForwardedDate(emailBodyText);
	if (forwarded) {
		const fromEmail = resolveOcrReceiptDate(forwarded, null, uploadDate);
		if (fromEmail.transaction_date) {
			return { ...fromEmail, dateSource: 'forwarded-email' };
		}
	}

	// 3. No date anywhere — surface it so the caller can warn the user.
	return { transaction_date: null, suspicious_date: false, dateSource: 'none' };
}

