/**
 * Tests for the hoisted email-receipt date handling.
 *
 * Pure data — no Mistral, no network. `extractForwardedDate` is timezone-proof
 * (it reads only the literal calendar tokens), so no fake timers are needed for
 * it. `resolveEmailReceiptDate` calls `isSuspiciousDate`, which reads the real
 * clock, so those cases pin "today" with fake timers like receiptDateCorrection.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { extractForwardedDate, resolveEmailReceiptDate } from './emailReceiptDate.ts';

describe('extractForwardedDate — mail-client header formats', () => {
	it('parses the Gmail forward header ("Jul 6, 2026 at 2:32 PM")', () => {
		expect(extractForwardedDate('Date: Mon, Jul 6, 2026 at 2:32 PM')).toBe('2026-07-06');
	});

	it('parses the Apple Mail header ("July 6, 2026 at 2:32:00 PM EDT")', () => {
		expect(extractForwardedDate('Date: July 6, 2026 at 2:32:00 PM EDT')).toBe('2026-07-06');
	});

	it('parses the Outlook "Sent:" header ("Monday, July 6, 2026 2:32 PM")', () => {
		expect(extractForwardedDate('Sent: Monday, July 6, 2026 2:32 PM')).toBe('2026-07-06');
	});

	it('parses the raw RFC 2822 Date header ("6 Jul 2026 14:32:00 -0400")', () => {
		expect(extractForwardedDate('Date: Mon, 6 Jul 2026 14:32:00 -0400')).toBe('2026-07-06');
	});

	it('parses an ISO 8601 Date header', () => {
		expect(extractForwardedDate('Date: 2026-07-06')).toBe('2026-07-06');
	});

	it('ignores the time/timezone — a near-midnight offset does not shift the day', () => {
		// 23:59 -0400 would roll to the next UTC day if we round-tripped through an
		// instant. We read only the calendar tokens, so it stays Jul 6.
		expect(extractForwardedDate('Date: Mon, 6 Jul 2026 23:59:00 -0400')).toBe('2026-07-06');
	});

	it('finds the header inside a full quoted forward block', () => {
		const body = [
			'Here is my receipt, thanks!',
			'',
			'---------- Forwarded message ---------',
			'From: Amazon <no-reply@amazon.ca>',
			'Date: Mon, Jul 6, 2026 at 2:32 PM',
			'Subject: Your order has shipped',
			'To: <me@example.com>',
			'',
			'Order total: $42.00'
		].join('\n');
		expect(extractForwardedDate(body)).toBe('2026-07-06');
	});

	it('handles quote-prefixed header lines', () => {
		expect(extractForwardedDate('> Date: 6 Jul 2026 09:00:00 -0400')).toBe('2026-07-06');
	});

	it('takes the first (most recent) header in a forward-of-a-forward', () => {
		const body = [
			'Date: Wed, Jul 8, 2026 at 9:00 AM',
			'Subject: Fwd: Fwd: receipt',
			'',
			'Date: Mon, Jul 6, 2026 at 2:32 PM',
			'Subject: receipt'
		].join('\n');
		expect(extractForwardedDate(body)).toBe('2026-07-08');
	});

	it('rejects bare numeric dates (DD/MM vs MM/DD is ambiguous)', () => {
		expect(extractForwardedDate('Date: 06/07/2026')).toBeNull();
	});

	it('rejects impossible calendar dates', () => {
		expect(extractForwardedDate('Date: Feb 30, 2026')).toBeNull();
	});

	it('ignores dates in prose that are not on a Date:/Sent: header line', () => {
		expect(extractForwardedDate('Your package was delivered on July 6, 2026.')).toBeNull();
	});

	it('returns null for missing or dateless bodies', () => {
		expect(extractForwardedDate(null)).toBeNull();
		expect(extractForwardedDate('')).toBeNull();
		expect(extractForwardedDate('Just some text with no header.')).toBeNull();
	});
});

describe('resolveEmailReceiptDate — one null-date handler for all paths', () => {
	beforeEach(() => {
		vi.useFakeTimers();
		vi.setSystemTime(new Date('2026-07-09T12:00:00Z'));
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	const today = () => new Date(2026, 6, 9); // 2026-07-09 local

	it("uses the receipt's own date when present and does not consult the email", () => {
		const out = resolveEmailReceiptDate(
			'2026-07-08',
			'2026/07/08',
			'Date: Jan 1, 2020', // stale forwarded date must be ignored
			today()
		);
		expect(out).toEqual({
			transaction_date: '2026-07-08',
			suspicious_date: false,
			dateSource: 'receipt'
		});
	});

	it('falls back to a recent forwarded-email date when the receipt has none', () => {
		const out = resolveEmailReceiptDate(
			null,
			null,
			'Date: Mon, Jul 6, 2026 at 2:32 PM',
			today()
		);
		expect(out).toEqual({
			transaction_date: '2026-07-06',
			suspicious_date: false,
			dateSource: 'forwarded-email'
		});
	});

	it('flags a stale forwarded-email date via the 42-day suspicious window', () => {
		const out = resolveEmailReceiptDate(null, null, 'Date: May 1, 2026', today());
		expect(out.transaction_date).toBe('2026-05-01'); // ~69 days old
		expect(out.suspicious_date).toBe(true);
		expect(out.dateSource).toBe('forwarded-email');
	});

	it("returns dateSource 'none' when neither receipt nor email yields a date", () => {
		const out = resolveEmailReceiptDate(null, null, 'No headers here.', today());
		expect(out).toEqual({
			transaction_date: null,
			suspicious_date: false,
			dateSource: 'none'
		});
	});
});

